solution.code:
async function batchPenulis(ids) {
  const baris = await ambilPenulisBanyak(ids);
  return ids.map((id) => baris.find((p) => p.id === id) ?? null);
}

function buatContext({ headers }) {
  const auth = headers.authorization ?? "";
  const token = auth.replace("Bearer ", "");
  return {
    user: cariPenggunaDariToken(token),
    pemuatPenulis: new DataLoader(batchPenulis),
  };
}

const resolvers = {
  Query: {
    buku: (parent, { id }) => bukuDb.find((b) => b.id === id) ?? null,
    daftarBuku: (parent, { kategori, batas }) => {
      const n = Math.min(batas ?? 10, 20);
      const hasil = kategori ? bukuDb.filter((b) => b.kategori === kategori) : bukuDb;
      return hasil.slice(0, n);
    },
    saya: (parent, args, ctx) => {
      if (!ctx.user) throw new Error("Kamu belum login");
      return ctx.user;
    },
  },
  Mutation: {
    pinjamBuku: (parent, { input }, ctx) => {
      if (!ctx.user) throw new Error("Kamu belum login");
      const buku = bukuDb.find((b) => b.id === input.bukuId);
      if (!buku) throw new Error("Buku tidak ditemukan");
      if (buku.stok < 1) throw new Error("Stok buku habis");
      buku.stok -= 1;
      const pinjam = { id: peminjamanDb.length + 1, buku, siswa: ctx.user };
      peminjamanDb.push(pinjam);
      return pinjam;
    },
  },
  Buku: {
    penulis: (buku, args, ctx) => ctx.pemuatPenulis.load(buku.penulisId),
  },
  Penulis: {
    buku: (penulis) => bukuDb.filter((b) => b.penulisId === penulis.id),
  },
};

const tipe = {
  "Query.buku": "Buku",
  "Query.daftarBuku": "Buku",
  "Query.saya": "Siswa",
  "Buku.penulis": "Penulis",
  "Penulis.buku": "Buku",
  "Mutation.pinjamBuku": "Peminjaman",
  "Peminjaman.buku": "Buku",
  "Peminjaman.siswa": "Siswa",
};

const api = buatGraphQL(resolvers, tipe);

project.setup:
// mini-graphql: a small GraphQL executor for exercises. Paste into `setup`.
// const api = buatGraphQL({ Query: { buku: (parent, args, ctx) => ... }, Mutation: {...}, Buku: { penulis: (buku, args, ctx) => ... } });
// const hasil = await api.jalankan(`query { buku(id: 1) { judul penulis { nama } } }`, { variabel }, ctx);
// -> { data } or { data: null, errors: [{ message }] }. Supports: query/mutation (named or anonymous), nested
// selections, arguments (int, float, string, boolean, null, enum, list, object, $variables), aliases, __typename,
// fragments are NOT supported. A field with no resolver reads parent[field]. Resolvers may be async.
// api.hitung[ "Tipe.field" ] counts resolver calls (for N+1 lessons). Types of objects come from resolver map keys:
// a value's type is taken from `__typename` on the object, or from api.tipe[ "Parent.field" ] = "Tipe" hints.
function buatGraphQL(resolvers, tipe = {}) {
  function lex(src) {
    const t = [];
    const re = /\s*(?:(#[^\n]*)|("(?:[^"\\]|\\.)*")|(-?\d+\.\d+)|(-?\d+)|(\.\.\.)|([A-Za-z_][A-Za-z0-9_]*)|(\$[A-Za-z_][A-Za-z0-9_]*)|([{}():\[\],!=@])|(\S))/y;
    let m;
    re.lastIndex = 0;
    while (re.lastIndex < src.length && (m = re.exec(src))) {
      if (m[1]) continue;
      if (m[2]) t.push({ k: "str", v: JSON.parse(m[2]) });
      else if (m[3]) t.push({ k: "num", v: parseFloat(m[3]) });
      else if (m[4]) t.push({ k: "num", v: parseInt(m[4], 10) });
      else if (m[5]) throw new Error("Fragment belum didukung di latihan ini");
      else if (m[6]) t.push({ k: "name", v: m[6] });
      else if (m[7]) t.push({ k: "var", v: m[7].slice(1) });
      else if (m[8]) t.push({ k: "p", v: m[8] });
      else if (m[9]) throw new Error("Syntax Error: karakter tidak dikenal " + m[9]);
      if (/^\s*$/.test(src.slice(re.lastIndex))) break;
    }
    return t;
  }
  function parse(src) {
    const t = lex(src);
    let i = 0;
    const peek = () => t[i];
    const eat = (v) => { const x = t[i]; if (!x || (v && x.v !== v)) throw new Error(`Syntax Error: diharapkan "${v}", dapat "${x ? x.v : "akhir query"}"`); i++; return x; };
    function value() {
      const x = eat();
      if (x.k === "var") return { var: x.v };
      if (x.k === "str" || x.k === "num") return x.v;
      if (x.k === "name") return x.v === "true" ? true : x.v === "false" ? false : x.v === "null" ? null : x.v;
      if (x.v === "[") { const a = []; while (peek().v !== "]") { a.push(value()); if (peek().v === ",") i++; } eat("]"); return a; }
      if (x.v === "{") { const o = {}; while (peek().v !== "}") { const k = eat().v; eat(":"); o[k] = value(); if (peek().v === ",") i++; } eat("}"); return o; }
      throw new Error("Syntax Error: nilai tidak valid " + x.v);
    }
    function args() {
      const a = {};
      if (peek() && peek().v === "(") { eat("("); while (peek().v !== ")") { const k = eat().v; eat(":"); a[k] = value(); if (peek().v === ",") i++; } eat(")"); }
      return a;
    }
    function selection() {
      eat("{");
      const s = [];
      while (peek() && peek().v !== "}") {
        let name = eat().v, alias = name;
        if (peek() && peek().v === ":") { eat(":"); name = eat().v; }
        const a = args();
        const sub = peek() && peek().v === "{" ? selection() : null;
        s.push({ alias, name, args: a, sub });
        if (peek() && peek().v === ",") i++;
      }
      eat("}");
      return s;
    }
    let op = "query";
    if (peek() && peek().k === "name" && (peek().v === "query" || peek().v === "mutation")) {
      op = eat().v;
      if (peek() && peek().k === "name") eat();
      if (peek() && peek().v === "(") { eat("("); while (peek().v !== ")") eat(); eat(")"); }
    }
    const sel = selection();
    if (i < t.length) throw new Error("Syntax Error: ada teks setelah akhir query");
    return { op, sel };
  }
  const resolve = (v, vars) => (v && typeof v === "object" && "var" in v ? vars[v.var] ?? null
    : Array.isArray(v) ? v.map((x) => resolve(x, vars))
    : v && typeof v === "object" ? Object.fromEntries(Object.entries(v).map(([k, x]) => [k, resolve(x, vars)])) : v);
  const hitung = {};
  async function field(typeName, parent, f, vars, ctx) {
    if (f.name === "__typename") return typeName;
    const fn = resolvers[typeName] && resolvers[typeName][f.name];
    const key = typeName + "." + f.name;
    hitung[key] = (hitung[key] || 0) + 1;
    const a = resolve(f.args, vars);
    const val = fn ? await fn(parent, a, ctx) : parent == null ? null : parent[f.name];
    if (!f.sub) return val === undefined ? null : val;
    if (val == null) return null;
    const child = (o) => (o && o.__typename) || tipe[key] || key;
    const one = async (o) => { if (o == null) return null; const out = {}; for (const s of f.sub) out[s.alias] = await field(child(o), o, s, vars, ctx); return out; };
    return Array.isArray(val) ? Promise.all(val.map(one)) : one(val);
  }
  return {
    hitung,
    tipe,
    reset() { for (const k of Object.keys(hitung)) delete hitung[k]; },
    async jalankan(query, variabel = {}, ctx = {}) {
      try {
        const { op, sel } = parse(query);
        const root = op === "mutation" ? "Mutation" : "Query";
        if (!resolvers[root]) throw new Error(`Skema tidak punya tipe ${root}`);
        const data = {};
        for (const f of sel) {
          if (f.name !== "__typename" && !(f.name in resolvers[root])) throw new Error(`Cannot query field "${f.name}" on type "${root}".`);
          data[f.alias] = await field(root, null, f, variabel, ctx);
        }
        return { data };
      } catch (e) {
        return { data: null, errors: [{ message: e.message }] };
      }
    },
  };
}
// DataLoader mini: tiruan kecil paket dataloader dengan API yang sama:
// new DataLoader(async (keys) => nilai dengan urutan sama seperti keys), lalu loader.load(key).
// Panggilan load() yang terjadi hampir bersamaan dikumpulkan jadi satu batch; key yang sama di-cache.
class DataLoader {
  constructor(batchFn) { this.batchFn = batchFn; this.cache = new Map(); this.antre = []; }
  load(key) {
    if (this.cache.has(key)) return this.cache.get(key);
    const p = new Promise((resolve, reject) => {
      this.antre.push({ key, resolve, reject });
      if (this.antre.length === 1) this._jadwalkan();
    });
    this.cache.set(key, p);
    return p;
  }
  async _jadwalkan() {
    for (let i = 0; i < 50; i++) await null; // tunggu resolver lain sempat memanggil load()
    const antre = this.antre;
    this.antre = [];
    try {
      const hasil = await this.batchFn(antre.map((a) => a.key));
      antre.forEach((a, i) => a.resolve(hasil[i]));
    } catch (e) { antre.forEach((a) => a.reject(e)); }
  }
}
const penulisDb = [
  { id: 1, nama: "Tere Liye" },
  { id: 2, nama: "Andrea Hirata" },
  { id: 3, nama: "Pramoedya Ananta Toer" },
];
const bukuDb = [
  { id: 1, judul: "Laskar Pelangi", kategori: "novel", penulisId: 2, stok: 3 },
  { id: 2, judul: "Bumi", kategori: "novel", penulisId: 1, stok: 0 },
  { id: 3, judul: "Bumi Manusia", kategori: "sejarah", penulisId: 3, stok: 2 },
  { id: 4, judul: "Sang Pemimpi", kategori: "novel", penulisId: 2, stok: 1 },
  { id: 5, judul: "Hujan", kategori: "novel", penulisId: 1, stok: 4 },
];
const siswaDb = [
  { id: 1, nama: "Rina", kelas: "XI RPL 1" },
  { id: 2, nama: "Budi", kelas: "XI TKJ 2" },
];
const peminjamanDb = [];
const tokenDb = { "token-rina": 1, "token-budi": 2 };
function cariPenggunaDariToken(token) {
  const id = tokenDb[token];
  return siswaDb.find((s) => s.id === id) ?? null;
}
// anggap ini SELECT * FROM penulis WHERE id IN (...): urutan baris tidak dijamin
let panggilanPenulis = 0;
async function ambilPenulisBanyak(ids) {
  panggilanPenulis++;
  return penulisDb.filter((p) => ids.includes(p.id)).sort((a, b) => b.id - a.id).map((p) => ({ ...p }));
}
// membuat objek request palsu dengan header Authorization untuk tes
const masuk = (token) => ({ headers: token ? { authorization: "Bearer " + token } : {} });

chapters.body:
## Tujuan

- Menjelaskan apa itu GraphQL dan bedanya dengan cara kerja REST.
- Mengenali masalah over-fetching dan under-fetching pada API.
- Membaca query GraphQL sederhana dan menebak bentuk JSON hasilnya.
- Menentukan kapan GraphQL cocok dipakai dan kapan REST lebih masuk akal.

## Dari REST ke GraphQL

Di kelas Desain REST API kamu sudah terbiasa dengan pola resource: setiap data punya URL sendiri, misalnya `/buku/1` untuk satu buku dan `/penulis/7` untuk satu penulis. Klien memilih method HTTP, server membalas JSON dengan bentuk yang sudah ditentukan oleh server. Pola ini sederhana dan sangat umum.

GraphQL datang dengan sudut pandang lain. GraphQL adalah bahasa query untuk API yang awalnya dikembangkan di Facebook untuk aplikasi mobile mereka, lalu dibuka untuk umum pada tahun 2015. Sekarang spesifikasinya dikelola oleh GraphQL Foundation, dan implementasinya tersedia untuk hampir semua bahasa: JavaScript, Python, PHP, Go, Java, dan lain-lain.

Ide utamanya ada tiga:

1. **Satu endpoint.** Hampir semua request dikirim ke satu alamat, biasanya `POST /graphql`. Tidak ada `/buku`, `/penulis`, dan `/peminjaman` yang terpisah.
2. **Klien memilih field.** Klien menulis query yang menyebut field apa saja yang ia butuhkan, dan server hanya mengirim field itu.
3. **Schema bertipe.** Server mengumumkan semua tipe data dan relasinya dalam sebuah schema. Schema ini menjadi kontrak: klien tahu persis apa yang boleh diminta, dan server menolak query yang tidak sesuai.

## Bentuk query dan hasilnya

Bayangkan aplikasi perpustakaan sekolah. Halaman detail buku ingin menampilkan judul buku dan nama penulisnya. Query GraphQL-nya seperti ini:

```graphql
query {
  buku(id: 1) {
    judul
    penulis {
      nama
    }
  }
}
```

Server menjawab dengan JSON yang bentuknya meniru query:

```json
{
  "data": {
    "buku": {
      "judul": "Laskar Pelangi",
      "penulis": { "nama": "Andrea Hirata" }
    }
  }
}
```

Perhatikan polanya. Kunci di JSON sama dengan nama field di query, dan susunan bersarangnya juga sama. Kalau besok halaman itu juga butuh harga, klien cukup menambahkan `harga` di bawah `judul`. Server tidak perlu diubah selama field `harga` sudah ada di schema.

![Query GraphQL dan bentuk hasilnya](slide:2)

Hasil selalu dibungkus di kunci `data`. Kalau ada masalah, server menambahkan kunci `errors` yang berisi daftar pesan. Kamu akan membahas bentuk ini lebih dalam di bab Error dan Validasi.

## Over-fetching dan under-fetching

Dua masalah klasik di API REST menjadi alasan GraphQL lahir.

**Over-fetching** artinya klien menerima data lebih banyak dari yang dibutuhkan. Misalnya endpoint `GET /buku` mengembalikan 20 field per buku: judul, sinopsis panjang, ISBN, tahun terbit, nama rak, stok, harga, dan seterusnya. Padahal halaman daftar di aplikasi HP hanya menampilkan judul dan sampul. Sisanya terbuang, memakan kuota dan memperlambat aplikasi, apalagi saat sinyal di sekolah sedang lemah.

**Under-fetching** adalah kebalikannya: satu endpoint tidak cukup, sehingga klien harus memanggil beberapa endpoint berturut-turut. Halaman detail buku tadi di REST bisa butuh tiga request:

```text
GET /buku/1           -> dapat penulisId: 1
GET /penulis/1        -> dapat nama penulis
GET /buku/1/ulasan    -> dapat ulasan siswa
```

Request kedua baru bisa dikirim setelah jawaban pertama datang, karena `penulisId` baru diketahui dari situ. Setiap bolak-balik ke server menambah waktu tunggu.

Di REST, solusinya biasanya membuat endpoint khusus, misalnya `/buku/1?include=penulis,ulasan`, atau endpoint baru untuk setiap layar. Lama-lama jumlah endpoint dan variasinya membengkak. GraphQL menyelesaikan keduanya dengan satu cara: klien menulis sendiri bentuk data yang diinginkan dalam satu query, termasuk data relasinya.

```graphql
{
  buku(id: 1) {
    judul
    penulis { nama }
    ulasan { isi bintang }
  }
}
```

Satu request, tidak ada field berlebih, tidak ada request tambahan.

## Bagaimana request GraphQL dikirim

Secara teknis, GraphQL tetap berjalan di atas HTTP. Klien biasanya mengirim `POST` ke `/graphql` dengan body JSON:

```json
{
  "query": "{ buku(id: 1) { judul } }",
  "variables": {}
}
```

Di JavaScript, kamu bisa mengirimnya dengan `fetch` biasa:

```js
const res = await fetch("https://perpus.sch.id/graphql", {
  method: "POST",
  headers: { "Content-Type": "application/json" },
  body: JSON.stringify({ query: "{ buku(id: 1) { judul } }" }),
});
const hasil = await res.json();
console.log(hasil.data.buku.judul);
```

Jadi tidak ada sihir. GraphQL hanyalah cara yang disepakati untuk menulis permintaan data di dalam body request, ditambah aturan tentang bagaimana server membacanya.

## Kapan GraphQL, kapan REST

GraphQL bukan pengganti wajib REST. Keduanya punya kekuatan masing-masing.

GraphQL terasa menguntungkan ketika:

- Ada banyak klien dengan kebutuhan berbeda, misalnya aplikasi web admin, aplikasi HP siswa, dan layar kios di perpustakaan.
- Data saling terhubung erat: buku, penulis, peminjaman, siswa, kelas.
- Satu layar butuh data dari banyak sumber sekaligus.
- Tim frontend ingin bergerak cepat tanpa menunggu backend membuat endpoint baru.

REST sering lebih masuk akal ketika:

- API-nya sederhana, misalnya hanya CRUD beberapa resource.
- Kamu ingin memanfaatkan cache HTTP dan CDN secara penuh. Karena GraphQL memakai satu URL dan biasanya `POST`, cache HTTP biasa tidak bisa langsung bekerja.
- Ada banyak upload file atau unduhan besar. GraphQL bisa melakukannya, tetapi lebih repot.
- API-nya publik dan dipakai pihak luar yang lebih familiar dengan REST.

Di dunia nyata, banyak sistem memakai keduanya. Misalnya, upload foto profil lewat endpoint REST, sementara data aplikasi diambil lewat GraphQL.

## Mencoba dengan mini-graphql

Di latihan kelas ini kamu memakai `buatGraphQL`, sebuah mesin GraphQL kecil yang sudah disiapkan. Ia tidak sekomplet library asli, tetapi cara pakainya mirip: kamu memberi objek resolver, lalu menjalankan query.

```js
const api = buatGraphQL({
  Query: {
    salam: () => "Halo dari kantin sekolah",
  },
});
const hasil = await api.jalankan("{ salam }");
// hasil: { data: { salam: "Halo dari kantin sekolah" } }
```

Objek `Query` berisi fungsi untuk setiap field paling atas. Fungsi ini disebut resolver, dan kamu akan membahasnya tuntas di bab Resolver. Untuk sekarang cukup pahami bahwa `Query.salam` adalah fungsi yang menghasilkan nilai untuk field `salam`.

Kalau field yang kamu kembalikan berupa objek atau array objek, field di dalamnya otomatis dibaca dari properti objek itu. Jadi resolver `daftarBuku: () => BUKU` sudah cukup untuk query `{ daftarBuku { judul harga } }`, dan hasilnya hanya berisi `judul` dan `harga` walaupun objek aslinya punya banyak properti lain. Inilah cara GraphQL mencegah over-fetching: server bisa punya data lengkap, tetapi hanya mengirim yang diminta.

## Istilah yang akan sering kamu temui

- **Operasi**: satu permintaan GraphQL. Jenisnya `query` untuk membaca, `mutation` untuk mengubah, dan `subscription` untuk data realtime.
- **Field**: satu potong data yang diminta, misalnya `judul` atau `penulis`.
- **Schema**: daftar lengkap tipe dan field yang disediakan server.
- **Resolver**: fungsi di server yang mengisi nilai satu field.

Empat istilah ini menjadi kerangka seluruh kelas. Bab berikutnya membahas schema, lalu query, resolver, dan mutation secara berurutan.

## Rangkuman

- GraphQL adalah bahasa query untuk API dengan satu endpoint, biasanya `POST /graphql`.
- Klien memilih field yang dibutuhkan, dan JSON hasilnya meniru bentuk query di dalam kunci `data`.
- GraphQL mengatasi over-fetching (data berlebih) dan under-fetching (request berulang) dalam satu query.
- Schema bertipe menjadi kontrak antara klien dan server.
- REST tetap cocok untuk API sederhana, cache HTTP, dan upload file; banyak sistem memakai keduanya.

