exercises.setup:
// mini-graphql: a small GraphQL executor for exercises. Paste into `setup`.
// const api = buatGraphQL({ Query: { buku: (parent, args, ctx) => ... }, Mutation: {...}, Buku: { penulis: (buku, args, ctx) => ... } });
// const hasil = await api.jalankan(`query { buku(id: 1) { judul penulis { nama } } }`, { variabel }, ctx);
// -> { data } or { data: null, errors: [{ message }] }. Supports: query/mutation (named or anonymous), nested
// selections, arguments (int, float, string, boolean, null, enum, list, object, $variables), aliases, __typename,
// fragments are NOT supported. A field with no resolver reads parent[field]. Resolvers may be async.
// api.hitung[ "Tipe.field" ] counts resolver calls (for N+1 lessons). Types of objects come from resolver map keys:
// a value's type is taken from `__typename` on the object, or from api.tipe[ "Parent.field" ] = "Tipe" hints.
function buatGraphQL(resolvers, tipe = {}) {
  function lex(src) {
    const t = [];
    const re = /\s*(?:(#[^\n]*)|("(?:[^"\\]|\\.)*")|(-?\d+\.\d+)|(-?\d+)|(\.\.\.)|([A-Za-z_][A-Za-z0-9_]*)|(\$[A-Za-z_][A-Za-z0-9_]*)|([{}():\[\],!=@])|(\S))/y;
    let m;
    re.lastIndex = 0;
    while (re.lastIndex < src.length && (m = re.exec(src))) {
      if (m[1]) continue;
      if (m[2]) t.push({ k: "str", v: JSON.parse(m[2]) });
      else if (m[3]) t.push({ k: "num", v: parseFloat(m[3]) });
      else if (m[4]) t.push({ k: "num", v: parseInt(m[4], 10) });
      else if (m[5]) throw new Error("Fragment belum didukung di latihan ini");
      else if (m[6]) t.push({ k: "name", v: m[6] });
      else if (m[7]) t.push({ k: "var", v: m[7].slice(1) });
      else if (m[8]) t.push({ k: "p", v: m[8] });
      else if (m[9]) throw new Error("Syntax Error: karakter tidak dikenal " + m[9]);
      if (/^\s*$/.test(src.slice(re.lastIndex))) break;
    }
    return t;
  }
  function parse(src) {
    const t = lex(src);
    let i = 0;
    const peek = () => t[i];
    const eat = (v) => { const x = t[i]; if (!x || (v && x.v !== v)) throw new Error(`Syntax Error: diharapkan "${v}", dapat "${x ? x.v : "akhir query"}"`); i++; return x; };
    function value() {
      const x = eat();
      if (x.k === "var") return { var: x.v };
      if (x.k === "str" || x.k === "num") return x.v;
      if (x.k === "name") return x.v === "true" ? true : x.v === "false" ? false : x.v === "null" ? null : x.v;
      if (x.v === "[") { const a = []; while (peek().v !== "]") { a.push(value()); if (peek().v === ",") i++; } eat("]"); return a; }
      if (x.v === "{") { const o = {}; while (peek().v !== "}") { const k = eat().v; eat(":"); o[k] = value(); if (peek().v === ",") i++; } eat("}"); return o; }
      throw new Error("Syntax Error: nilai tidak valid " + x.v);
    }
    function args() {
      const a = {};
      if (peek() && peek().v === "(") { eat("("); while (peek().v !== ")") { const k = eat().v; eat(":"); a[k] = value(); if (peek().v === ",") i++; } eat(")"); }
      return a;
    }
    function selection() {
      eat("{");
      const s = [];
      while (peek() && peek().v !== "}") {
        let name = eat().v, alias = name;
        if (peek() && peek().v === ":") { eat(":"); name = eat().v; }
        const a = args();
        const sub = peek() && peek().v === "{" ? selection() : null;
        s.push({ alias, name, args: a, sub });
        if (peek() && peek().v === ",") i++;
      }
      eat("}");
      return s;
    }
    let op = "query";
    if (peek() && peek().k === "name" && (peek().v === "query" || peek().v === "mutation")) {
      op = eat().v;
      if (peek() && peek().k === "name") eat();
      if (peek() && peek().v === "(") { eat("("); while (peek().v !== ")") eat(); eat(")"); }
    }
    const sel = selection();
    if (i < t.length) throw new Error("Syntax Error: ada teks setelah akhir query");
    return { op, sel };
  }
  const resolve = (v, vars) => (v && typeof v === "object" && "var" in v ? vars[v.var] ?? null
    : Array.isArray(v) ? v.map((x) => resolve(x, vars))
    : v && typeof v === "object" ? Object.fromEntries(Object.entries(v).map(([k, x]) => [k, resolve(x, vars)])) : v);
  const hitung = {};
  async function field(typeName, parent, f, vars, ctx) {
    if (f.name === "__typename") return typeName;
    const fn = resolvers[typeName] && resolvers[typeName][f.name];
    const key = typeName + "." + f.name;
    hitung[key] = (hitung[key] || 0) + 1;
    const a = resolve(f.args, vars);
    const val = fn ? await fn(parent, a, ctx) : parent == null ? null : parent[f.name];
    if (!f.sub) return val === undefined ? null : val;
    if (val == null) return null;
    const child = (o) => (o && o.__typename) || tipe[key] || key;
    const one = async (o) => { if (o == null) return null; const out = {}; for (const s of f.sub) out[s.alias] = await field(child(o), o, s, vars, ctx); return out; };
    return Array.isArray(val) ? Promise.all(val.map(one)) : one(val);
  }
  return {
    hitung,
    tipe,
    reset() { for (const k of Object.keys(hitung)) delete hitung[k]; },
    async jalankan(query, variabel = {}, ctx = {}) {
      try {
        const { op, sel } = parse(query);
        const root = op === "mutation" ? "Mutation" : "Query";
        if (!resolvers[root]) throw new Error(`Skema tidak punya tipe ${root}`);
        const data = {};
        for (const f of sel) {
          if (f.name !== "__typename" && !(f.name in resolvers[root])) throw new Error(`Cannot query field "${f.name}" on type "${root}".`);
          data[f.alias] = await field(root, null, f, variabel, ctx);
        }
        return { data };
      } catch (e) {
        return { data: null, errors: [{ message: e.message }] };
      }
    },
  };
}

const PENULIS = [
  { id: 1, nama: "Andrea Hirata" },
  { id: 2, nama: "Tere Liye" },
  { id: 3, nama: "Rina Wati" },
  { id: 4, nama: "Joko Santoso" },
];
const BUKU = [
  { id: 1, judul: "Laskar Pelangi", kategori: "FIKSI", harga: 85000, stok: 3, penulisId: 1 },
  { id: 2, judul: "Bumi", kategori: "FIKSI", harga: 95000, stok: 0, penulisId: 2 },
  { id: 3, judul: "Fisika Dasar", kategori: "SAINS", harga: 60000, stok: 4, penulisId: 3 },
  { id: 4, judul: "Sang Pemimpi", kategori: "FIKSI", harga: 80000, stok: 5, penulisId: 1 },
  { id: 5, judul: "Sejarah Nusantara", kategori: "SEJARAH", harga: 75000, stok: 2, penulisId: 4 },
];

const api = buatGraphQL(
  {
    Query: {
      buku: (_, { id }) => BUKU.find((b) => b.id === Number(id)) ?? null,
      daftarBuku: (_, { kategori }) => (kategori ? BUKU.filter((b) => b.kategori === kategori) : BUKU),
    },
    Buku: {
      penulis: (buku) => PENULIS.find((p) => p.id === buku.penulisId),
    },
  },
  { "Query.buku": "Buku", "Query.daftarBuku": "Buku", "Buku.penulis": "Penulis" }
);

chapters.body:
## Tujuan

- Menjelaskan peran resolver sebagai fungsi pengisi nilai setiap field.
- Memakai tiga argumen resolver: `parent`, `args`, dan `context`.
- Memanfaatkan resolver bawaan dan menulis resolver untuk field yang dihitung.
- Menulis resolver bersarang dan resolver async yang membaca data dari context.

## Schema berkata apa, resolver berkata bagaimana

Schema hanya menggambarkan bentuk data. Schema tidak tahu dari mana data itu berasal. Tugas mengambil data ada di **resolver**: fungsi yang dipanggil server untuk mengisi nilai satu field.

```js
const resolvers = {
  Query: {
    daftarBuku: () => BUKU,
    buku: (parent, args) => BUKU.find((b) => b.id === Number(args.id)) ?? null,
  },
};
```

Objek `resolvers` disusun mengikuti schema. Kunci tingkat pertama adalah nama tipe (`Query`, `Buku`, `Penulis`), kunci di dalamnya adalah nama field. Jadi `resolvers.Query.buku` adalah resolver untuk field `buku` di tipe `Query`.

Sumber datanya bebas. Resolver boleh membaca array di memori seperti contoh di atas, menjalankan query SQL, memanggil API REST lain, atau membaca cache Redis. Klien tidak perlu tahu. Ini salah satu kekuatan GraphQL: kamu bisa memindahkan data dari satu database ke database lain tanpa mengubah satu query pun di aplikasi HP.

## Tiga argumen resolver

Setiap resolver dipanggil dengan argumen yang sama:

```js
(parent, args, context, info) => { ... }
```

![Tiga argumen resolver](slide:13)

- **parent** adalah hasil resolver di level atasnya. Untuk field di `Query`, parent biasanya kosong karena tidak ada level di atasnya. Untuk `Buku.penulis`, parent adalah objek buku yang sedang diproses.
- **args** berisi argumen yang ditulis klien di query. Query `buku(id: 3)` membuat `args` bernilai `{ id: 3 }`, atau `{ id: "3" }` di server asli karena tipe `ID` dikirim sebagai string.
- **context** adalah objek yang sama untuk semua resolver dalam satu request. Tempatnya menaruh data bersama: user yang sedang login, koneksi database, atau loader. Context dibuat ulang untuk setiap request, jadi data milik satu siswa tidak bocor ke request siswa lain.
- **info** berisi detail teknis tentang query, seperti nama field dan path. Pemula jarang membutuhkannya.

Argumen yang tidak dipakai biasa diberi nama `_` atau `__` supaya jelas sengaja diabaikan:

```js
Query: {
  salam: (_, __, ctx) => (ctx.user ? "Halo, " + ctx.user.nama : "Halo, tamu"),
}
```

## Resolver bawaan

Kamu tidak perlu menulis resolver untuk setiap field. Kalau sebuah field tidak punya resolver, server memakai **resolver bawaan** (default resolver) yang membaca properti dengan nama sama dari parent. Di implementasi JavaScript resmi, kalau properti itu berupa fungsi, fungsi itu dipanggil.

```js
const resolvers = {
  Query: {
    buku: (_, { id }) => BUKU.find((b) => b.id === Number(id)) ?? null,
  },
  Buku: {
    // judul, harga, stok: cukup resolver bawaan
    tersedia: (buku) => buku.stok > 0,
  },
};
```

Saat klien meminta `buku(id: 1) { judul tersedia }`, server memanggil `Query.buku` dan mendapat objek buku. Untuk `judul`, tidak ada resolver, jadi server membaca `buku.judul`. Untuk `tersedia`, ada resolver, jadi server memanggilnya dengan objek buku sebagai parent.

Aturannya sederhana: tulis resolver hanya untuk field yang nilainya **dihitung** atau **diambil dari tempat lain**. Field yang sudah ada di objek, biarkan resolver bawaan bekerja.

## Resolver bersarang

Relasi antar tipe diisi oleh resolver di tipe anak. Misalnya data buku hanya menyimpan `penulisId`, bukan objek penulis lengkap. Field `Buku.penulis` perlu resolver:

```js
Buku: {
  penulis: (buku) => PENULIS.find((p) => p.id === buku.penulisId),
},
Penulis: {
  buku: (penulis) => BUKU.filter((b) => b.penulisId === penulis.id),
},
```

Bayangkan query ini:

```graphql
{
  buku(id: 4) {
    judul
    penulis {
      nama
      buku { judul }
    }
  }
}
```

Urutan kerjanya seperti menuruni tangga:

1. `Query.buku` dipanggil dengan `args.id = 4`, hasilnya objek Sang Pemimpi.
2. Objek itu menjadi parent. `judul` dibaca resolver bawaan, `Buku.penulis` dipanggil dan mengembalikan Andrea Hirata.
3. Objek penulis menjadi parent berikutnya. `nama` dibaca resolver bawaan, `Penulis.buku` mengembalikan dua buku.
4. Untuk setiap buku di list itu, `judul` dibaca resolver bawaan.

Setiap resolver hanya perlu memikirkan satu langkah: "diberi parent ini, apa nilai field saya?" Server yang menyusun semuanya menjadi satu JSON.

## Resolver async

Data di aplikasi nyata hampir selalu diambil dari database, dan aksesnya asinkron. Resolver boleh mengembalikan Promise atau ditulis sebagai fungsi `async`. Server menunggu Promise selesai sebelum turun ke level berikutnya.

```js
const resolvers = {
  Query: {
    buku: async (_, { id }, ctx) => ctx.db.cariBuku(Number(id)),
  },
  Buku: {
    penulis: async (buku, _, ctx) => ctx.db.cariPenulis(buku.penulisId),
  },
};
```

Perhatikan bahwa koneksi database diambil dari `ctx.db`, bukan dari variabel global. Dengan cara ini resolver mudah diuji: saat testing, kamu cukup memberi context berisi database palsu. Di latihan kedua, kamu akan membuktikannya sendiri dengan dua database berbeda.

Di mini-graphql latihan, context dikirim sebagai argumen ketiga: `api.jalankan(query, {}, { db, user })`. Di server asli seperti Apollo Server, context dibuat oleh fungsi khusus untuk setiap request. Itu dibahas di bab Server GraphQL dengan Node.js.

## Petunjuk tipe di latihan

Server asli tahu bahwa `Query.buku` mengembalikan `Buku` dari schema. Mini-graphql tidak membaca SDL, jadi kamu memberi petunjuk di argumen kedua `buatGraphQL`:

```js
const tipe = {
  "Query.buku": "Buku",
  "Buku.penulis": "Penulis",
  "Penulis.buku": "Buku",
};
const api = buatGraphQL(resolvers, tipe);
```

Tanpa petunjuk itu, resolver `Buku.penulis` tidak akan dipanggil, karena mesin tidak tahu bahwa objek hasil `Query.buku` bertipe `Buku`.

## Menguji resolver secara langsung

Karena resolver hanyalah fungsi JavaScript biasa, kamu bisa mengujinya tanpa server sama sekali. Panggil saja dengan parent, args, dan context buatanmu sendiri:

```js
const hasil = resolvers.Buku.tersedia({ judul: "Bumi", stok: 0 });
console.log(hasil); // false

const buku = await resolvers.Query.buku(null, { id: "1" }, { db: dbPalsu });
console.log(buku.judul);
```

Cara ini sangat membantu saat mencari bug. Kalau hasil query salah, uji resolver di level yang mencurigakan secara terpisah. Kamu akan cepat tahu apakah masalahnya ada di pengambilan data, di perhitungan field, atau di petunjuk tipe.

Kebiasaan ini juga mendorong resolver tetap kecil. Kalau sebuah resolver sulit diuji karena terlalu banyak bergantung pada variabel global, itu tanda logikanya perlu dipindah ke context atau ke fungsi terpisah, misalnya modul `layananBuku` yang dipanggil oleh beberapa resolver sekaligus.

## Kesalahan umum

- Lupa mengubah `args.id` menjadi angka, sehingga `find` tidak pernah cocok.
- Mengembalikan `undefined` saat data tidak ada. Lebih jelas kembalikan `null`.
- Menulis resolver untuk field yang sebenarnya cukup dibaca resolver bawaan.
- Menyimpan data per pengguna di variabel global, bukan di context.

## Rangkuman

- Resolver adalah fungsi yang mengisi nilai satu field, disusun per tipe lalu per field.
- Argumennya `parent`, `args`, `context`, dan `info`.
- Field tanpa resolver dibaca dari properti parent dengan nama yang sama.
- Hasil resolver menjadi parent untuk resolver di level bawahnya.
- Resolver boleh async, dan data bersama seperti database atau user diambil dari context.

