solution.code:
const resolvers = {
  Query: {
    buku: (_, { id }) => BUKU.find((b) => b.id === Number(id)) ?? null,
  },
  Mutation: {
    tambahBuku: (_, { input }) => {
      if (!input.judul || !input.judul.trim()) throw new Error("Judul wajib diisi");
      if (!(input.harga > 0)) throw new Error("Harga harus lebih dari 0");
      const id = Math.max(...BUKU.map((b) => b.id)) + 1;
      const buku = { id, stok: 1, ...input };
      BUKU.push(buku);
      return buku;
    },
    pinjamBuku: (_, { bukuId }) => {
      const buku = BUKU.find((b) => b.id === Number(bukuId));
      if (!buku) throw new Error("Buku tidak ditemukan");
      if (buku.stok === 0) throw new Error("Stok habis");
      buku.stok -= 1;
      const pinjam = { id: PEMINJAMAN.length + 1, bukuId: buku.id };
      PEMINJAMAN.push(pinjam);
      return pinjam;
    },
  },
  Peminjaman: {
    buku: (p) => BUKU.find((b) => b.id === p.bukuId),
  },
};

const api = buatGraphQL(resolvers, {
  "Query.buku": "Buku",
  "Mutation.tambahBuku": "Buku",
  "Mutation.pinjamBuku": "Peminjaman",
  "Peminjaman.buku": "Buku",
});

