// mini-graphql: a small GraphQL executor for exercises. Paste into `setup`.
// const api = buatGraphQL({ Query: { buku: (parent, args, ctx) => ... }, Mutation: {...}, Buku: { penulis: (buku, args, ctx) => ... } });
// const hasil = await api.jalankan(`query { buku(id: 1) { judul penulis { nama } } }`, { variabel }, ctx);
// -> { data } or { data: null, errors: [{ message }] }. Supports: query/mutation (named or anonymous), nested
// selections, arguments (int, float, string, boolean, null, enum, list, object, $variables), aliases, __typename,
// fragments are NOT supported. A field with no resolver reads parent[field]. Resolvers may be async.
// api.hitung[ "Tipe.field" ] counts resolver calls (for N+1 lessons). Types of objects come from resolver map keys:
// a value's type is taken from `__typename` on the object, or from api.tipe[ "Parent.field" ] = "Tipe" hints.
function buatGraphQL(resolvers, tipe = {}) {
  function lex(src) {
    const t = [];
    const re = /\s*(?:(#[^\n]*)|("(?:[^"\\]|\\.)*")|(-?\d+\.\d+)|(-?\d+)|(\.\.\.)|([A-Za-z_][A-Za-z0-9_]*)|(\$[A-Za-z_][A-Za-z0-9_]*)|([{}():\[\],!=@])|(\S))/y;
    let m;
    re.lastIndex = 0;
    while (re.lastIndex < src.length && (m = re.exec(src))) {
      if (m[1]) continue;
      if (m[2]) t.push({ k: "str", v: JSON.parse(m[2]) });
      else if (m[3]) t.push({ k: "num", v: parseFloat(m[3]) });
      else if (m[4]) t.push({ k: "num", v: parseInt(m[4], 10) });
      else if (m[5]) throw new Error("Fragment belum didukung di latihan ini");
      else if (m[6]) t.push({ k: "name", v: m[6] });
      else if (m[7]) t.push({ k: "var", v: m[7].slice(1) });
      else if (m[8]) t.push({ k: "p", v: m[8] });
      else if (m[9]) throw new Error("Syntax Error: karakter tidak dikenal " + m[9]);
      if (/^\s*$/.test(src.slice(re.lastIndex))) break;
    }
    return t;
  }
  function parse(src) {
    const t = lex(src);
    let i = 0;
    const peek = () => t[i];
    const eat = (v) => { const x = t[i]; if (!x || (v && x.v !== v)) throw new Error(`Syntax Error: diharapkan "${v}", dapat "${x ? x.v : "akhir query"}"`); i++; return x; };
    function value() {
      const x = eat();
      if (x.k === "var") return { var: x.v };
      if (x.k === "str" || x.k === "num") return x.v;
      if (x.k === "name") return x.v === "true" ? true : x.v === "false" ? false : x.v === "null" ? null : x.v;
      if (x.v === "[") { const a = []; while (peek().v !== "]") { a.push(value()); if (peek().v === ",") i++; } eat("]"); return a; }
      if (x.v === "{") { const o = {}; while (peek().v !== "}") { const k = eat().v; eat(":"); o[k] = value(); if (peek().v === ",") i++; } eat("}"); return o; }
      throw new Error("Syntax Error: nilai tidak valid " + x.v);
    }
    function args() {
      const a = {};
      if (peek() && peek().v === "(") { eat("("); while (peek().v !== ")") { const k = eat().v; eat(":"); a[k] = value(); if (peek().v === ",") i++; } eat(")"); }
      return a;
    }
    function selection() {
      eat("{");
      const s = [];
      while (peek() && peek().v !== "}") {
        let name = eat().v, alias = name;
        if (peek() && peek().v === ":") { eat(":"); name = eat().v; }
        const a = args();
        const sub = peek() && peek().v === "{" ? selection() : null;
        s.push({ alias, name, args: a, sub });
        if (peek() && peek().v === ",") i++;
      }
      eat("}");
      return s;
    }
    let op = "query";
    if (peek() && peek().k === "name" && (peek().v === "query" || peek().v === "mutation")) {
      op = eat().v;
      if (peek() && peek().k === "name") eat();
      if (peek() && peek().v === "(") { eat("("); while (peek().v !== ")") eat(); eat(")"); }
    }
    const sel = selection();
    if (i < t.length) throw new Error("Syntax Error: ada teks setelah akhir query");
    return { op, sel };
  }
  const resolve = (v, vars) => (v && typeof v === "object" && "var" in v ? vars[v.var] ?? null
    : Array.isArray(v) ? v.map((x) => resolve(x, vars))
    : v && typeof v === "object" ? Object.fromEntries(Object.entries(v).map(([k, x]) => [k, resolve(x, vars)])) : v);
  const hitung = {};
  async function field(typeName, parent, f, vars, ctx) {
    if (f.name === "__typename") return typeName;
    const fn = resolvers[typeName] && resolvers[typeName][f.name];
    const key = typeName + "." + f.name;
    hitung[key] = (hitung[key] || 0) + 1;
    const a = resolve(f.args, vars);
    const val = fn ? await fn(parent, a, ctx) : parent == null ? null : parent[f.name];
    if (!f.sub) return val === undefined ? null : val;
    if (val == null) return null;
    const child = (o) => (o && o.__typename) || tipe[key] || key;
    const one = async (o) => { if (o == null) return null; const out = {}; for (const s of f.sub) out[s.alias] = await field(child(o), o, s, vars, ctx); return out; };
    return Array.isArray(val) ? Promise.all(val.map(one)) : one(val);
  }
  return {
    hitung,
    tipe,
    reset() { for (const k of Object.keys(hitung)) delete hitung[k]; },
    async jalankan(query, variabel = {}, ctx = {}) {
      try {
        const { op, sel } = parse(query);
        const root = op === "mutation" ? "Mutation" : "Query";
        if (!resolvers[root]) throw new Error(`Skema tidak punya tipe ${root}`);
        const data = {};
        for (const f of sel) {
          if (f.name !== "__typename" && !(f.name in resolvers[root])) throw new Error(`Cannot query field "${f.name}" on type "${root}".`);
          data[f.alias] = await field(root, null, f, variabel, ctx);
        }
        return { data };
      } catch (e) {
        return { data: null, errors: [{ message: e.message }] };
      }
    },
  };
}

const PENULIS = [
  { id: 1, nama: "Andrea Hirata" },
  { id: 2, nama: "Tere Liye" },
  { id: 3, nama: "Rina Wati" },
  { id: 4, nama: "Joko Santoso" },
];
const BUKU = [
  { id: 1, judul: "Laskar Pelangi", kategori: "FIKSI", harga: 85000, stok: 3, penulisId: 1 },
  { id: 2, judul: "Bumi", kategori: "FIKSI", harga: 95000, stok: 0, penulisId: 2 },
  { id: 3, judul: "Fisika Dasar", kategori: "SAINS", harga: 60000, stok: 4, penulisId: 3 },
  { id: 4, judul: "Sang Pemimpi", kategori: "FIKSI", harga: 80000, stok: 5, penulisId: 1 },
  { id: 5, judul: "Sejarah Nusantara", kategori: "SEJARAH", harga: 75000, stok: 2, penulisId: 4 },
];

const PEMINJAMAN = [];

chapters.body:
## Tujuan

- Membaca bentuk respons GraphQL yang berisi `data` dan `errors`.
- Menjelaskan kenapa server GraphQL sering menjawab HTTP 200 walaupun ada error.
- Melempar error dari resolver dengan pesan yang jelas dan memberi kode lewat `extensions.code`.
- Memvalidasi input mutation sebelum data disimpan.

## Bentuk respons GraphQL

Di kelas REST kamu terbiasa membaca status code dulu: 200 berarti berhasil, 404 berarti data tidak ada, 422 berarti input salah. Setiap endpoint punya status sendiri, dan klien memutuskan langkah berikutnya dari angka itu.

GraphQL bekerja sedikit berbeda. Semua permintaan masuk ke satu endpoint, misalnya `POST /graphql`, dan jawabannya selalu berupa objek JSON dengan bentuk yang sudah ditentukan spesifikasi. Ada dua kunci utama:

- `data`: hasil query, bentuknya mengikuti selection set yang kamu minta.
- `errors`: daftar error, hanya muncul kalau ada yang salah.

Kalau semuanya lancar, respons hanya berisi `data`:

```json
{
  "data": {
    "buku": { "judul": "Laskar Pelangi", "stok": 3 }
  }
}
```

Kalau ada masalah, kunci `errors` ikut muncul. Setiap error minimal punya `message`, dan server biasanya menambahkan `path` (field mana yang gagal) serta `locations` (baris dan kolom di teks query):

```json
{
  "data": { "buku": null },
  "errors": [
    {
      "message": "Buku sedang diperbaiki, coba lagi nanti",
      "path": ["buku"],
      "locations": [{ "line": 1, "column": 3 }]
    }
  ]
}
```

Jadi tugas klien GraphQL adalah memeriksa `errors` dulu, bukan hanya status HTTP. Library klien seperti Apollo Client atau urql sudah melakukan pemeriksaan ini untukmu, tapi kamu tetap perlu paham bentuknya.

![Bentuk respons data dan errors](slide:19)

## Kenapa HTTP 200 padahal ada error

Ini bagian yang sering membingungkan orang yang datang dari REST. Satu permintaan GraphQL bisa meminta banyak field sekaligus. Bayangkan halaman beranda perpustakaan sekolah yang meminta daftar buku baru, profil siswa, dan jumlah denda dalam satu query. Kalau hanya field denda yang gagal karena layanan keuangan sedang mati, apakah seluruh permintaan harus dianggap gagal? Tidak. Daftar buku dan profil tetap bisa ditampilkan.

Karena itu server GraphQL umumnya menjawab **HTTP 200** untuk query yang berhasil dijalankan, walaupun sebagian field menghasilkan error. Status HTTP hanya menjawab pertanyaan "apakah permintaan ini sampai dan bisa diproses?", sedangkan detail kegagalan ada di dalam `errors`.

Ada pengecualian. Kalau query-nya sendiri rusak, misalnya salah ketik kurung kurawal atau meminta field yang tidak ada di schema, query itu bahkan tidak dijalankan. Banyak server menjawab kasus ini dengan status 400, dan `data` tidak ada sama sekali. Perilaku persisnya berbeda antar server dan antar versi, jadi biasakan membaca isi `errors`, jangan bergantung pada status saja.

## Partial data dan nilai null

Di server GraphQL sungguhan, error pada satu field tidak menghapus seluruh hasil. Field yang gagal diisi `null`, sisanya tetap dikirim. Inilah yang disebut **partial data**. Tapi ada aturan penting: kalau field yang gagal bertipe non-null (pakai `!`), `null` tidak boleh ada di situ, sehingga `null` "naik" ke field induk terdekat yang boleh null. Kalau sampai ke akar, `data` menjadi `null`.

Karena itu, pilih tanda `!` dengan sadar. Field yang mungkin gagal karena bergantung pada layanan lain sebaiknya dibiarkan nullable supaya kegagalannya tidak merusak seluruh respons.

Catatan untuk latihan: mini-graphql yang kita pakai di kelas ini lebih sederhana. Begitu satu resolver melempar error, hasilnya langsung `{ data: null, errors: [{ message }] }`. Jadi di latihan kamu akan melihat `data: null`, sedangkan di server asli sebagian data mungkin tetap ada.

## Error dari resolver

Cara paling sederhana membuat error adalah melempar `Error` biasa dari resolver. Server menangkapnya dan memasukkan pesannya ke `errors`:

```js
const resolvers = {
  Mutation: {
    pinjamBuku: (parent, { bukuId }, ctx) => {
      const buku = bukuDb.find((b) => b.id === bukuId);
      if (!buku) throw new Error("Buku tidak ditemukan");
      if (buku.stok === 0) throw new Error("Stok buku habis");
      buku.stok -= 1;
      return buku;
    },
  },
};
```

Perhatikan bedanya dengan "data tidak ada" pada query. Untuk `Query.buku(id: 99)`, kebiasaan yang umum adalah mengembalikan `null`, bukan error. Klien cukup memeriksa apakah `buku` bernilai `null`, mirip 404 di REST. Error dipakai ketika sesuatu benar-benar tidak bisa dikerjakan, misalnya meminjam buku yang stoknya habis.

Hati-hati juga dengan pesan error. Error tak terduga, misalnya koneksi database putus, jangan sampai membocorkan detail seperti nama tabel atau password ke klien. Server seperti Apollo Server bisa menyembunyikan stack trace di mode produksi dan menyediakan pengaturan untuk menyaring pesan error sebelum dikirim.

## Kode error dengan extensions

Pesan error ditujukan untuk manusia dan bisa berubah kapan saja, misalnya diterjemahkan. Klien butuh sesuatu yang stabil untuk diperiksa oleh kode. Untuk itu spesifikasi GraphQL menyediakan kunci `extensions` di setiap error, tempat server menaruh info tambahan. Kebiasaan yang dipakai luas adalah `extensions.code`:

```json
{
  "errors": [
    {
      "message": "Stok buku habis",
      "path": ["pinjamBuku"],
      "extensions": { "code": "STOK_HABIS" }
    }
  ]
}
```

Di Node.js, kamu bisa membuat error seperti ini dengan kelas `GraphQLError` dari paket `graphql`:

```js
import { GraphQLError } from "graphql";

throw new GraphQLError("Stok buku habis", {
  extensions: { code: "STOK_HABIS" },
});
```

Beberapa kode sudah umum dipakai, misalnya `BAD_USER_INPUT` untuk input yang salah, `UNAUTHENTICATED` untuk pengguna yang belum login, `FORBIDDEN` untuk pengguna yang tidak punya izin, dan `INTERNAL_SERVER_ERROR` untuk error tak terduga. Kamu juga boleh membuat kode sendiri seperti `STOK_HABIS`, asalkan didokumentasikan untuk tim frontend. Di klien, kodenya diperiksa seperti ini:

```js
const kode = hasil.errors?.[0]?.extensions?.code;
if (kode === "UNAUTHENTICATED") arahkanKeLogin();
```

mini-graphql di latihan hanya menyimpan `message`, jadi `extensions` tidak akan muncul di sana. Konsepnya tetap sama ketika kamu pindah ke server sungguhan.

## Validasi input

GraphQL sudah melakukan sebagian validasi untukmu. Kalau argumen bertipe `Int!` diisi teks, atau field wajib di input type tidak diisi, server menolak query sebelum resolver berjalan. Ini keuntungan besar dibanding REST, karena pemeriksaan tipe dasar datang gratis dari schema.

Tapi schema tidak tahu aturan bisnis. Schema tidak bisa berkata "judul minimal 3 karakter" atau "stok tidak boleh negatif". Aturan seperti itu kamu tulis sendiri di resolver mutation, sebelum data disimpan:

```js
tambahBuku: (parent, { input }) => {
  const judul = input.judul.trim();
  if (judul.length < 3) throw new Error("Judul minimal 3 karakter");
  if (input.stok < 0) throw new Error("Stok tidak boleh negatif");
  const buku = { id: bukuDb.length + 1, judul, stok: input.stok };
  bukuDb.push(buku);
  return buku;
},
```

Urutannya penting: periksa semua aturan dulu, baru ubah data. Kalau kamu menyimpan dulu lalu baru memeriksa, data yang salah sudah terlanjur masuk. Pada aplikasi yang lebih besar, validasi biasanya dipindah ke fungsi tersendiri atau memakai library seperti zod, lalu error-nya diberi kode `BAD_USER_INPUT` supaya form di frontend bisa menampilkan pesan di bawah kolom yang salah.

Ada juga pendekatan lain yang dipakai sebagian tim: mutation tidak melempar error untuk kesalahan input, melainkan mengembalikan objek hasil yang berisi daftar kesalahan, misalnya `{ buku, kesalahan: [{ field, pesan }] }`. Cara ini membuat kesalahan input menjadi bagian schema sehingga terlihat jelas oleh klien. Kedua cara sama-sama sah; yang penting konsisten di seluruh API.

## Rangkuman

- Respons GraphQL berisi `data` dan, bila ada masalah, `errors` yang setiap elemennya punya `message`, biasanya juga `path` dan `locations`.
- Server umumnya menjawab HTTP 200 untuk query yang dijalankan walaupun ada error field; query yang rusak atau tidak valid sering dijawab 400.
- Di server asli, field yang gagal menjadi `null` dan data lain tetap dikirim; mini-graphql di latihan langsung mengembalikan `data: null`.
- Data yang tidak ditemukan cukup dikembalikan `null`; lempar error bila aksi benar-benar tidak bisa dikerjakan.
- `extensions.code` memberi kode stabil seperti `BAD_USER_INPUT` atau `UNAUTHENTICATED` untuk diperiksa klien.
- Schema memeriksa tipe, sedangkan aturan bisnis kamu validasi sendiri di resolver sebelum menyimpan data.

