};

const api = buatGraphQL(resolvers);

solution.code:
function halaman(daftar, first, after) {
  const batas = Math.min(first ?? 2, 10);
  const mulai = after == null ? 0 : daftar.findIndex((b) => String(b.id) === after) + 1;
  const potong = daftar.slice(mulai, mulai + batas);
  const edges = potong.map((b) => ({ cursor: String(b.id), node: b }));
  return {
    edges,
    pageInfo: {
      hasNextPage: mulai + batas < daftar.length,
      endCursor: edges.length ? edges[edges.length - 1].cursor : null,
    },
  };
}

const resolvers = {
  Query: {
    daftarBuku: (parent, { first, after }) => halaman(bukuDb, first, after),
  },
};

